#!/usr/bin/env python3
"""Honorific revisions checked against the Agency for Cultural Affairs guidance."""
import json, html
import quiz_audit as qa
import v9_apply_batch1 as b
prior=json.loads((b.OUT/'changes.json').read_text()); assert len(prior)==1029
_,Q,A=qa.audit(str(b.DST)); D=json.loads((b.OUT/'decisions.json').read_text()); extra=[]
def rewrite(qid,key,stem,opts,exps,reason,verdicts):
 assert len(opts)==len(exps)==len(verdicts)==4
 assert int(A['A_'+qid[2:]]['ans'])==key
 old_stem=[Q[qid]['stem']]; new_stem=[stem]
 if qid=='Q_2_023':
  from docx import Document
  ps=Document(b.DST).paragraphs
  old_stem=[ps[i].text for i in (512,513,514)]
  new_stem=['【会話】学習者：「先生、昨日の宿題を持って参りました。ご覧になってください。」','教師：「ありがとう。じゃあ、ここに置いておいてね。」','この会話の敬語形式と依頼表現について、文化審議会『敬語の指針』の考え方に照らし、最も適切な分析を一つ選びなさい。']
 for field,old,new in [('stem',old_stem,new_stem),('options',Q[qid]['opts'],opts),('explanations',A['A_'+qid[2:]]['txt'],exps)]:
  for i,(before,after) in enumerate(zip(old,new)):
   if html.unescape(before)==after: continue
   extra.append(dict(id=qid,field=field,index=None if field=='stem' else i,before=html.unescape(before),after=after,reason=reason,sources=['S04'],applied=True,before_version='第49修正バッチ作業稿'))
 D[qid].update(status='確認済み',fixes_applied=True,independent_answer=key,sources=['S04'],option_verdicts=verdicts,reason=reason,stem_review='公式答申の該当節と場面条件を照合し全4肢を判定。',explanation_review='全4解説を公式本文と照合。地域・場面を超える全称命題を撤去。',unresolved='',multiple_correct_risk='なし：指定した指針と場面条件で正答のみ適合',no_correct_risk='なし：独立正答'+str(key))
rewrite('Q_2_020',1,
 '文化審議会『敬語の指針』が示す全国共通語の敬語の基本的な考え方に関する記述として、最も適切なものを一つ選びなさい。ここでは、改まった場面で身内を自分側の人物として扱って話す場合を考える。',
 ['自分の父の発言を話し相手に丁重に伝える場合、「父が申しておりました」と謙譲語Ⅱを用いることができる。','身内を自分側として扱う場合でも、その人物の行為には必ず尊敬語を用いて、その人物を立てなければならない。','「父が申しておりました」の「申す」は、父を立てる尊敬語である。','同指針は、会社内で上司を立てる場合と、社外の人にその上司を自分側として扱って話す場合とで、敬語の選択を変えてはならないとしている。'],
 ['謙譲語Ⅱは、自分側の行為などを話し相手に丁重に述べる敬語です。父を自分側として扱うという条件では、「申す」を用いることができます。','指針の基本原則は、尊敬語・謙譲語Ⅰを使って自分側を立てないことです。ただし、方言敬語や場面による違いも説明されており、あらゆる家族への敬語を一律に誤りとする趣旨ではありません。','「申す」は謙譲語Ⅱの例です。この用法で丁重に述べる相手は聞き手であり、父を立てる尊敬語ではありません。','指針は、社員だけの会と社外の人が多くいる会とで、社長への敬語の選択を変える例を示しています。所属だけから、すべての場面で同じ形式を使うとはできません。'],
 '父のウチ扱いと改まった全国共通語の条件を明示。家族への尊敬語を全場面で否定する説明とウチ・ソト境界の絶対則を撤去。指針第2章3・6、第3章2・7と照合。',
 ['謙譲語Ⅱと自分側の条件に適合','自分側を立てない基本原則と不一致','申すの分類を誤る','社内外で選択を変える指針の例と不一致'])
rewrite('Q_2_021',1,
 '文化審議会『敬語の指針』における「二重敬語」と「敬語連結」の説明として、最も適切なものを一つ選びなさい。下線等にかかわらず、ここで「れる・られる」は尊敬の意味で用いるものとする。',
 ['「お読みになる」に尊敬の「れる」をさらに加えた「お読みになられる」は、一つの語に同じ種類の敬語を重ねた二重敬語である。','「ご覧になる」に尊敬の「れる」を加えた「ご覧になられる」は、二つの語を「て」で結ぶ敬語連結である。','一つの文に尊敬語と謙譲語が一つずつあれば、異なる人物について用いていても必ず二重敬語になる。','「お読みになっていらっしゃる」は、「読む」と「いる」をそれぞれ敬語にして「て」で結ぶため、指針では二重敬語に分類される。'],
 ['指針は「お読みになられる」を二重敬語の例として示しています。二重敬語は一般に適切でないとされますが、習慣として定着した語もあります。','同じ語に尊敬の形式を重ねた二重敬語です。「て」で二つの語を結んだ敬語連結ではありません。','二重敬語の定義は、一つの語について同じ種類の敬語を重ねることです。一文に異なる敬語があることだけでは該当しません。','指針は、この形を敬語連結としています。個々の敬語の使い方が適切で、意味的な不合理がなければ基本的に許容されます。'],
 '尊敬のれるという条件を明示し、可能・受身との曖昧さを解消。指針の直接例によって二重敬語と敬語連結を区別。定着した二重敬語も存在する点を保持。',
 ['指針の定義と直接例に一致','てによる連結でなく分類違い','一語という定義条件を満たさない','指針では敬語連結'])
rewrite('Q_2_023',3,
 '【会話】学習者：「先生、昨日の宿題を持って参りました。ご覧になってください。」この会話の敬語形式と依頼表現について、文化審議会『敬語の指針』の考え方に照らし、最も適切な分析を一つ選びなさい。',
 ['「持って参りました」は、先生の動作を立てる尊敬語を学習者自身の動作に使った形である。','尊敬語を含む依頼は、相手の負担や場面にかかわらず、必ず最も適切な依頼になる。','「参る」は学習者側の動作を聞き手に丁重に述べる謙譲語Ⅱであり、「ご覧になる」は先生の動作を立てる尊敬語である。依頼の適切さは、これらの形式だけでなく、相手の負担や場面も踏まえて考える。','「ご覧になってください」は尊敬語を含んでいても、目上の人への依頼では場面にかかわらず使用が禁止される。'],
 ['「参る」は謙譲語Ⅱです。学習者自身の動作を先生に丁重に述べる用法であり、先生の動作を立てる尊敬語ではありません。','敬語の形式があることだけで依頼の適切さは決まりません。指針は相手の負担、前置き、関係や場面に応じた表現の選択を説明しています。','二つの形式の働きを正しく区別しています。例えば相手への負担を意識する場面では、前置きや「ご覧いただけますか」などを検討できますが、長い表現ほど常に良いとは限りません。','指針は「取ってください」を依頼・指示の表現として扱い、簡潔に頼める場面では回りくどい表現を用いない方がよい場合も示しています。目上への一律の禁止は導けません。'],
 '敬語形式の分類と依頼の場面適切性を区別。指針第2章1・3、第3章5の直接記述に限定し、てくださいの一律不適切・長い依頼の最高敬意という断定を撤去。',
 ['参るの分類が逆','形式だけによる普遍判断は指針に不一致','分類と場面による選択の両方に一致','指針は一律に禁止していない'])
rewrite('Q_2_024',2,
 '文化審議会『敬語の指針』第3章6の「マニュアル敬語」に関する説明として、最も適切なものを一つ選びなさい。',
 ['「御注文の品はおそろいになりましたでしょうか」の「おそろいになる」は、注文した品そのものを尊敬語で立てることが適切なので、指針が勧める形式である。','指針は、マニュアルという型を基礎としながらも、使う側と指導する側が表現を考え、工夫を重ねる姿勢が大切だとしている。','指針は、マニュアル敬語の問題はアルバイトの若者だけに特有であり、大人の接客には生じないとしている。','指針は、言葉の形式に問題がなければ、お客の顔を見ずに接客しても、敬意は必ず伝わるとしている。'],
 ['指針は「おそろいになる」が注文の品を立ててしまう点を問題とし、「そろいましたでしょうか」「以上でよろしいでしょうか」などを示しています。','指針は、マニュアルの型を基礎としつつ表現を考え、工夫することを、マニュアル敬語を生かすための条件としています。','指針は、若者や特定の店舗だけに特有の問題ではないと明記しています。','指針は、お客の顔を見ない接客などを例に、態度が言葉を裏切る場合や、形だけでは敬意が伝わらないことを説明しています。'],
 'よろしかったでしょうかのタ形を配慮に一義的に固定する未照合解釈を撤去。同じマニュアル敬語領域を保ち、公式指針第3章6の具体例と運用条件に差替え。',
 ['注文の品を立てることを指針は問題視','型と工夫の両方を重視する本文に一致','若者だけという限定に不一致','態度の重要性を否定し不一致'])
rewrite('Q_2_025',3,
 '文化審議会『敬語の指針』の分類において、話題の人物を立てる働きと、話や文章の相手に丁重・丁寧に述べる働きの区別について、最も適切なものを一つ選びなさい。',
 ['「参る」は、行為者が自分側かどうかに関係なく、その行為者を立てる尊敬語である。','「です・ます」は、話や文章の相手ではなく、話題の中の第三者を立てる尊敬語である。','尊敬語は行為者などを、謙譲語Ⅰは行為の向かう先を立てる。謙譲語Ⅱは自分側の行為などを話や文章の相手に丁重に述べ、丁寧語はその相手に丁寧に述べる。','謙譲語Ⅰと謙譲語Ⅱは、行為の向かう先と話し相手が異なる場合でも、敬語としての働きが常に同じである。'],
 ['「参る」は謙譲語Ⅱです。自分側の行為などを相手に丁重に述べる働きであり、行為者を立てる尊敬語ではありません。','「です・ます」は丁寧語として、話や文章の相手に丁寧さを添える形式です。話題の第三者を立てる働きと区別します。','指針の各分類の定義と一致します。誰を立てるかと、誰に丁重・丁寧に述べるかを区別することが要点です。','指針は、行為の向かう先と話し相手が異なる場合に、謙譲語Ⅰと謙譲語Ⅱの働きの違いに留意する必要を説明しています。'],
 '素材敬語・対話敬語という他体系の名称と公式指針の5分類を無出典で同一視せず、人物を立てる働きと聞き手への働きの比較を保持。社長に参るは常に誤りという場面不足の例を撤去。',
 ['参るを尊敬語に誤分類','です・ますの相手を取り違える','各分類の働きに一致','向かう先と相手の区別を否定'])
